{"implementation":"import math


def solve(case):
    if not isinstance(case, dict):
        raise ValueError("case must be a dictionary")
    for key in ("nodes", "required_symbols", "_case_nonce"):
        if key not in case:
            raise ValueError("missing required field: " + key)

    nodes = case["nodes"]
    required_symbols = case["required_symbols"]
    nonce = case["_case_nonce"]
    if not isinstance(nodes, list) or not nodes:
        raise ValueError("nodes must be a non-empty list")
    if not isinstance(required_symbols, list):
        raise ValueError("required_symbols must be a list")
    if not isinstance(nonce, str):
        raise ValueError("_case_nonce must be a string")

    required = []
    seen_symbols = set()
    for symbol in required_symbols:
        if not isinstance(symbol, str) or not symbol:
            raise ValueError("required symbols must be non-empty strings")
        if symbol in seen_symbols:
            raise ValueError("required_symbols contains duplicates")
        seen_symbols.add(symbol)
        required.append(symbol)

    by_id = {}
    source_ids = []
    for node in nodes:
        if not isinstance(node, dict):
            raise ValueError("each node must be a dictionary")
        for key in ("id", "parent", "symbol", "depth", "removable", "utility"):
            if key not in node:
                raise ValueError("node missing required field: " + key)
        node_id = node["id"]
        parent = node["parent"]
        symbol = node["symbol"]
        depth = node["depth"]
        removable = node["removable"]
        utility = node["utility"]
        if not isinstance(node_id, str) or not node_id:
            raise ValueError("node id must be a non-empty string")
        if node_id in by_id:
            raise ValueError("node ids must be unique")
        if parent is not None and (not isinstance(parent, str) or not parent):
            raise ValueError("parent must be null or a non-empty string")
        if not isinstance(symbol, str) or not symbol:
            raise ValueError("symbol must be a non-empty string")
        if isinstance(depth, bool) or not isinstance(depth, int) or depth < 0:
            raise ValueError("depth must be a non-negative integer")
        if not isinstance(removable, bool):
            raise ValueError("removable must be a boolean")
        if isinstance(utility, bool) or not isinstance(utility, (int, float)) or not math.isfinite(utility):
            raise ValueError("utility must be finite numeric")
        by_id[node_id] = {
            "id": node_id,
            "parent": parent,
            "symbol": symbol,
            "depth": depth,
            "removable": removable,
            "utility": utility,
        }
        source_ids.append(node_id)

    roots = [node for node in by_id.values() if node["parent"] is None]
    if len(roots) != 1:
        raise ValueError("tree must have exactly one root")
    root_id = roots[0]["id"]
    if roots[0]["depth"] != 0:
        raise ValueError("root depth must be zero")

    for node in by_id.values():
        parent = node["parent"]
        if parent is None:
            continue
        if parent not in by_id:
            raise ValueError("parent does not exist")
        if parent == node["id"]:
            raise ValueError("node cannot be its own parent")
        if by_id[parent]["depth"] != node["depth"] - 1:
            raise ValueError("parent and child depths are inconsistent")

    for node_id in source_ids:
        visited = set()
        current = node_id
        while by_id[current]["parent"] is not None:
            if current in visited:
                raise ValueError("tree contains a cycle")
            visited.add(current)
            current = by_id[current]["parent"]
        if current != root_id:
            raise ValueError("tree is disconnected")

    initial_symbols = {node["symbol"] for node in by_id.values()}
    if any(symbol not in initial_symbols for symbol in required):
        raise ValueError("required symbol is not represented")

    candidates = [node for node in by_id.values() if node["removable"] and node["id"] != root_id]
    candidates.sort(key=lambda node: (-node["depth"], node["id"]))
    registered_candidate_order = [node["id"] for node in candidates]

    retained = set(source_ids)
    removal_order = []
    for node in candidates:
        node_id = node["id"]
        if node_id not in retained:
            continue
        has_retained_child = any(
            other_id in retained and other["parent"] == node_id
            for other_id, other in by_id.items()
        )
        if has_retained_child:
            continue
        remaining_symbols = {
            by_id[other_id]["symbol"]
            for other_id in retained
            if other_id != node_id
        }
        if all(symbol in remaining_symbols for symbol in required):
            retained.remove(node_id)
            removal_order.append(node_id)

    retained_ids = sorted(retained)
    grammar_valid = all(
        node_id == root_id or by_id[node_id]["parent"] in retained
        for node_id in retained
    )
    interestingness_preserved = all(
        any(by_id[node_id]["symbol"] == symbol for node_id in retained)
        for symbol in required
    )
    if not grammar_valid or not interestingness_preserved:
        raise ValueError("reduction produced an infeasible result")

    retained_utility = sum(by_id[node_id]["utility"] for node_id in retained_ids)
    removed_utility = sum(by_id[node_id]["utility"] for node_id in removal_order)
    return {
        "retained_ids": retained_ids,
        "removal_order": removal_order,
        "retained_utility": retained_utility,
        "removed_utility": removed_utility,
        "grammar_valid": grammar_valid,
        "interestingness_preserved": interestingness_preserved,
        "registered_candidate_order": registered_candidate_order,
        "stable_ties": True,
    }
"}
